const { useState } = React;

function App() {
  const [page, setPage] = useState("general");
  const [displayName, setDisplayName] = useState("");
  const [email, setEmail] = useState("");
  const [language, setLanguage] = useState("English");
  const [timeZone, setTimeZone] = useState("");
  const [saved, setSaved] = useState(false);
  const [errors, setErrors] = useState({});

  const timeZones = [
    "UTC-12:00",
    "UTC-11:00",
    "UTC-10:00",
    "UTC-09:00",
    "UTC-08:00",
    "UTC-07:00",
    "UTC-06:00",
    "UTC-05:00",
    "UTC-04:00",
    "UTC-03:00",
    "UTC-02:00",
    "UTC-01:00",
    "UTC+00:00",
    "UTC+01:00",
    "UTC+02:00",
    "UTC+03:00",
    "UTC+04:00",
    "UTC+05:00",
    "UTC+06:00",
    "UTC+07:00",
    "UTC+08:00",
    "UTC+09:00",
    "UTC+10:00",
    "UTC+11:00",
    "UTC+12:00"
  ];

  function validate() {
    const newErrors = {};
    if (!displayName.trim()) {
      newErrors.displayName = "Display name is required.";
    }
    if (!email.trim()) {
      newErrors.email = "Email is required.";
    } else if (!/^\S+@\S+\.\S+$/.test(email)) {
      newErrors.email = "Email is invalid.";
    }
    if (!language) {
      newErrors.language = "Please select a language.";
    }
    if (!timeZone) {
      newErrors.timeZone = "Please select a time zone.";
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }

  function onSave() {
    if (validate()) {
      setSaved(true);
      setTimeout(() => setSaved(false), 3000);
    } else {
      setSaved(false);
    }
  }

  function renderSidebar() {
    const items = ["general", "security", "billing", "notifications"];
    const labels = {
      general: "General",
      security: "Security",
      billing: "Billing",
      notifications: "Notifications"
    };

    return (
      <nav aria-label="Settings navigation" style={styles.sidebar}>
        <ul style={styles.sidebarList}>
          {items.map((item) => (
            <li key={item} style={styles.sidebarItem}>
              <button
                type="button"
                onClick={() => setPage(item)}
                aria-current={page === item ? "page" : undefined}
                style={{
                  ...styles.sidebarButton,
                  fontWeight: page === item ? "bold" : "normal",
                  textDecoration: page === item ? "underline" : "none"
                }}
              >
                {labels[item]}
              </button>
            </li>
          ))}
        </ul>
      </nav>
    );
  }

  function renderGeneral() {
    return (
      <section aria-labelledby="general-heading" style={styles.content}>
        <h2 id="general-heading" style={styles.heading}>General</h2>
        <form
          onSubmit={(e) => {
            e.preventDefault();
            onSave();
          }}
          noValidate
          style={styles.form}
        >
          <label htmlFor="displayName" style={styles.label}>
            Display name
          </label>
          <input
            id="displayName"
            name="displayName"
            type="text"
            value={displayName}
            onChange={(e) => setDisplayName(e.target.value)}
            style={styles.input}
            aria-describedby={errors.displayName ? "displayName-error" : undefined}
          />
          {errors.displayName && (
            <p id="displayName-error" role="alert" style={styles.error}>
              {errors.displayName}
            </p>
          )}

          <label htmlFor="email" style={styles.label}>
            Email
          </label>
          <input
            id="email"
            name="email"
            type="email"
            placeholder="you@example.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={styles.input}
            aria-describedby={errors.email ? "email-error" : undefined}
          />
          {errors.email && (
            <p id="email-error" role="alert" style={styles.error}>
              {errors.email}
            </p>
          )}

          <label htmlFor="language" style={styles.label}>
            Language
          </label>
          <select
            id="language"
            name="language"
            value={language}
            onChange={(e) => setLanguage(e.target.value)}
            style={styles.select}
            aria-describedby={errors.language ? "language-error" : undefined}
          >
            <option value="English">English</option>
            <option value="Hindi">Hindi</option>
            <option value="Telugu">Telugu</option>
          </select>
          {errors.language && (
            <p id="language-error" role="alert" style={styles.error}>
              {errors.language}
            </p>
          )}

          <label htmlFor="timeZone" style={styles.label}>
            Time zone
          </label>
          <select
            id="timeZone"
            name="timeZone"
            value={timeZone}
            onChange={(e) => setTimeZone(e.target.value)}
            style={styles.select}
            aria-describedby={errors.timeZone ? "timeZone-error" : undefined}
          >
            <option value="" disabled>
              Select time zone
            </option>
            {timeZones.map((tz) => (
              <option key={tz} value={tz}>
                {tz}
              </option>
            ))}
          </select>
          {errors.timeZone && (
            <p id="timeZone-error" role="alert" style={styles.error}>
              {errors.timeZone}
            </p>
          )}

          <button type="submit" style={styles.saveButton}>
            Save changes
          </button>
          {saved && (
            <p role="alert" style={styles.savedMessage}>
              Settings saved
            </p>
          )}
        </form>
      </section>
    );
  }

  function renderSecurity() {
    return (
      <section aria-labelledby="security-heading" style={styles.content}>
        <h2 id="security-heading" style={styles.heading}>Security</h2>
        <p>This is the Security page.</p>
      </section>
    );
  }

  function renderBilling() {
    return (
      <section aria-labelledby="billing-heading" style={styles.content}>
        <h2 id="billing-heading" style={styles.heading}>Billing</h2>
        <p>This is the Billing page.</p>
      </section>
    );
  }

  function renderNotifications() {
    return (
      <section aria-labelledby="notifications-heading" style={styles.content}>
        <h2 id="notifications-heading" style={styles.heading}>Notifications</h2>
        <p>This is the Notifications page.</p>
      </section>
    );
  }

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen,
            Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
          background: #f9f9f6;
          color: #222;
        }
        button {
          cursor: pointer;
        }
      `}</style>
      <div style={styles.app}>
        {renderSidebar()}
        {page === "general" && renderGeneral()}
        {page === "security" && renderSecurity()}
        {page === "billing" && renderBilling()}
        {page === "notifications" && renderNotifications()}
      </div>
    </>
  );
}

const styles = {
  app: {
    display: "flex",
    minHeight: "100vh",
    backgroundColor: "#f9f9f6",
    color: "#222",
    fontSize: 16,
    lineHeight: 1.4
  },
  sidebar: {
    width: 180,
    backgroundColor: "#fff",
    borderRight: "1px solid #ccc",
    padding: "1rem 0",
    display: "flex",
    flexDirection: "column",
    alignItems: "flex-start"
  },
  sidebarList: {
    listStyle: "none",
    padding: 0,
